    def to_str(self) -> str:
        """Returns the string representation of the model using alias"""
        return pprint.pformat(self.model_dump(by_alias=True))

    def to_json(self) -> str:
        """Returns the JSON representation of the model using alias"""
        return json.dumps(to_jsonable_python(self.to_dict()))

    @classmethod
    def from_json(cls, json_str: str) -> Optional[Self]:
        """Create an instance of ExtractBatchPayloadInputsInner from a JSON string"""
        return cls.from_dict(json.loads(json_str))

    def to_dict(self) -> Dict[str, Any]:
        """Return the dictionary representation of the model using alias.

        This has the following differences from calling pydantic's
        `self.model_dump(by_alias=True)`:

        * `None` is only added to the output dict for nullable fields that
          were set at model initialization. Other fields with value `None`
          are ignored.
        """
        excluded_fields: Set[str] = set([
        ])

        _dict = self.model_dump(
            by_alias=True,
            exclude=excluded_fields,
            exclude_none=True,
        )
        # override the default output from pydantic by calling `to_dict()` of browser
        if self.browser:
            _dict['browser'] = self.browser.to_dict()
        # override the default output from pydantic by calling `to_dict()` of each item in browser_actions (list)
        _items = []
        if self.browser_actions:
            for _item_browser_actions in self.browser_actions:
                _items.append(_item_browser_actions.to_dict() if _item_browser_actions is not None else None)
            _dict['browser_actions'] = _items
        # override the default output from pydantic by calling `to_dict()` of cookies
        if self.cookies:
            _dict['cookies'] = self.cookies.to_dict()
        # override the default output from pydantic by calling `to_dict()` of file_parsing_options
        if self.file_parsing_options:
            _dict['file_parsing_options'] = self.file_parsing_options.to_dict()
        # override the default output from pydantic by calling `to_dict()` of each value in headers (dict)
        _field_dict = {}
        if self.headers:
            for _key_headers in self.headers:
                _field_dict[_key_headers] = self.headers[_key_headers].to_dict() if self.headers[_key_headers] is not None else None
            _dict['headers'] = _field_dict
        # override the default output from pydantic by calling `to_dict()` of each item in network_capture (list)
        _items = []
        if self.network_capture:
            for _item_network_capture in self.network_capture:
                _items.append(_item_network_capture.to_dict() if _item_network_capture is not None else None)
            _dict['network_capture'] = _items
        # override the default output from pydantic by calling `to_dict()` of parser
        if self.parser:
            _dict['parser'] = self.parser.to_dict()
        # override the default output from pydantic by calling `to_dict()` of render
        if self.render:
            _dict['render'] = self.render.to_dict()
        # override the default output from pydantic by calling `to_dict()` of session
        if self.session:
            _dict['session'] = self.session.to_dict()
        # override the default output from pydantic by calling `to_dict()` of skill
        if self.skill:
            _dict['skill'] = self.skill.to_dict()
        # set to None if body (nullable) is None
        # and model_fields_set contains the field
        if self.body is None and "body" in self.model_fields_set:
            _dict['body'] = None

        return _dict

